import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Assertions","description":"","frontmatter":{"title":"Assertions"},"headers":[],"relativePath":"invariants/assertions.md","filePath":"invariants/assertions.md"}'),i={name:"invariants/assertions.md"};function c(o,e,l,p,r,h){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="assertions" tabindex="-1">Assertions <a class="header-anchor" href="#assertions" aria-label="Permalink to &quot;Assertions&quot;">​</a></h1><p>When you define an assertion, you&#39;re asking Fault to find a solution to the model where your assertion is <em>not true</em>. Fault does this by negating the statements before generating the rules.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Fault assertion</th><th style="text-align:left;">SMT generated</th></tr></thead><tbody><tr><td style="text-align:left;"><code>x &gt; 3</code></td><td style="text-align:left;"><code>(&lt;= x 3)</code></td></tr><tr><td style="text-align:left;"><code>y == 4</code></td><td style="text-align:left;"><code>(not (= y 4))</code></td></tr><tr><td style="text-align:left;"><code>x &gt; 3 &amp;&amp; y == 4</code></td><td style="text-align:left;"><code>(or (&lt;= x 3) (not (= y 4)))</code></td></tr></tbody></table><h2 id="assertions-on-structs" tabindex="-1">Assertions on Structs <a class="header-anchor" href="#assertions-on-structs" aria-label="Permalink to &quot;Assertions on Structs&quot;">​</a></h2><p>You can write assertions for structs (the stock and flow defintions) and those assertions will include all instances of those structs.</p><p>The following assert in our cache spec</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert resources.table &lt;= 4;</span></span></code></pre></div><p>Becomes the this in SMT</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(assert (or </span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_0 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_1 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_2 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_3 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_4 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_5 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_6 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_7 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_8 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_9 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_10 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_11 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_12 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_13 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_14 4)</span></span>
<span class="line"><span>    (&gt; cache_r_machine_table_15 4)</span></span>
<span class="line"><span>))</span></span></code></pre></div><p>Notice that although the rule in Fault is for <code>resources.table</code> all the rules generated in SMT are for the instance of <code>resources</code> initialized in the instance of the flow declared in the run block.</p><h2 id="assertions-on-instances" tabindex="-1">Assertions on Instances <a class="header-anchor" href="#assertions-on-instances" aria-label="Permalink to &quot;Assertions on Instances&quot;">​</a></h2><p>Assertions can also be made for just a specific instance of a stock.</p><p>Instead of this</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert resources.table &lt;= 4;</span></span></code></pre></div><p>You can do this</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert r.machine.table &lt;= 4;</span></span></code></pre></div><h2 id="assertions-on-states" tabindex="-1">Assertions on States <a class="header-anchor" href="#assertions-on-states" aria-label="Permalink to &quot;Assertions on States&quot;">​</a></h2><p>Even the state chart can have assertions. For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert (replCache.lookupRecord &amp;&amp; !replCache.expire) || (!replCache.lookupRecord &amp;&amp; replCache.expire);</span></span></code></pre></div><p>...would assert that the cache cannot be looking up records while also deleting them.</p><p>When used in asserts, state are treated as booleans establishing whether the state is active or not.</p><h2 id="when-then" tabindex="-1">When/Then <a class="header-anchor" href="#when-then" aria-label="Permalink to &quot;When/Then&quot;">​</a></h2><p>The <code>when A then B</code> construction expresses a conditional invariant: B must be true whenever A is true. B may be false when A is false.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert when state.accessGranted then state.authenticated;</span></span></code></pre></div><p>This is equivalent to <code>assert !state.accessGranted || state.authenticated</code> but reads more clearly as an intent. It works with both <code>assert</code> and <code>assume</code>, and accepts temporal qualifiers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert when lock.heldByA then !lock.heldByB always;</span></span>
<span class="line"><span>assume when queue.full then queue.size &gt;= queue.capacity;</span></span></code></pre></div><p><code>when/then</code> can only be used in assertions and assumptions — not in state functions or run blocks.</p>`,27)])])}const _=s(i,[["render",c]]);export{u as __pageData,_ as default};
